document.addEventListener("DOMContentLoaded",()=>{const o=document.getElementById("countdown");if(!o)return;const c=window.otpExpiredTime*1e3,s=document.getElementById("timerContainer"),d=document.getElementById("resendContainer"),m=setInterval(()=>{const e=new Date().getTime(),t=c-e;if(t<0){clearInterval(m),s&&s.classList.add("hidden"),d&&d.classList.remove("hidden");return}const n=Math.floor(t%(1e3*60*60)/(1e3*60)),i=Math.floor(t%(1e3*60)/1e3);o.innerHTML=(n<10?"0"+n:n)+":"+(i<10?"0"+i:i)},1e3),r=document.getElementById("otpForm");r&&r.addEventListener("submit",function(){const e=this.querySelector('button[type="submit"]');e&&(e.disabled=!0,e.innerHTML='<i class="ph-bold ph-spinner animate-spin"></i> Memverifikasi...')})});
